// Docgen-SOLC: 0.8.15

pragma solidity ^0.8.15;

import { Owned } from "../utils/Owned.sol";

/**
 * @title   AdminProxy
 * @author  RedVeil
 * @notice  Ownes contracts in the vault ecosystem to allow for easy ownership changes.
 *
 * AdminProxy is controlled by VaultController. VaultController executes management functions on other contracts through `execute()`
 */
contract AdminProxy is Owned {
  constructor(address _owner) Owned(_owner) {}

  /// @notice Execute arbitrary management functions.
  function execute(address target, bytes calldata callData)
    external
    onlyOwner
    returns (bool success, bytes memory returndata)
  {
    return target.call(callData);
  }
}
"},"src/vault/CloneFactory.sol":{"content":"// SPDX-License-Identifier: GPL-3.0
// Docgen-SOLC: 0.8.15

pragma solidity ^0.8.15;

import { Clones } from "openzeppelin-contracts/proxy/Clones.sol";
import { Owned } from "../utils/Owned.sol";
import { Template } from "../interfaces/vault/ITemplateRegistry.sol";

/**
 * @title   CloneFactory
 * @author  RedVeil
 * @notice  Creates clones from a template and initializes it.
 *
 * Clones get created via the `DeploymentController`.
 */
contract CloneFactory is Owned {
  /*//////////////////////////////////////////////////////////////
                               IMMUTABLES
    //////////////////////////////////////////////////////////////*/

  /// @param _owner `AdminProxy`
  constructor(address _owner) Owned(_owner) {}

  /*//////////////////////////////////////////////////////////////
                          DEPLOY LOGIC
    //////////////////////////////////////////////////////////////*/

  event Deployment(address indexed clone);

  error DeploymentInitFailed();
  error NotEndorsed(bytes32 templateKey);

  /**
   * @notice Clones an implementation and initializes the clone. Caller must be owner. (`DeploymentController`)
   * @param template The template to use for the deployment. (See TemplateRegistry for more details)
   * @param data The data to pass to the clone's initializer.
   */
  function deploy(Template calldata template, bytes calldata data) external onlyOwner returns (address clone) {
    clone = Clones.clone(template.implementation);

    bool success = true;
    if (template.requiresInitData) (success, ) = clone.call(data);

    if (!success) revert DeploymentInitFailed();

    emit Deployment(clone);
  }
}
"},"src/vault/CloneRegistry.sol":{"content":"// SPDX-License-Identifier: GPL-3.0
// Docgen-SOLC: 0.8.15

pragma solidity ^0.8.15;

import { Owned } from "../utils/Owned.sol";

/**
 * @title   CloneRegistry
 * @author  RedVeil
 * @notice  Registers clones created by `CloneFactory`.
 *
 * Clones get saved on creation via `DeploymentController`.
 * Is used by `VaultController` to check if a target is a registerd clone.
 */
contract CloneRegistry is Owned {
  /*//////////////////////////////////////////////////////////////
                            IMMUTABLES
    //////////////////////////////////////////////////////////////*/

  /// @param _owner `AdminProxy`
  constructor(address _owner) Owned(_owner) {}

  /*//////////////////////////////////////////////////////////////
                          ADD CLONE LOGIC
    //////////////////////////////////////////////////////////////*/

  mapping(address => bool) public cloneExists;
  // TemplateCategory => TemplateId => Clones
  mapping(bytes32 => mapping(bytes32 => address[])) public clones;
  address[] public allClones;

  event CloneAdded(address clone);

  /**
   * @notice Add a clone to the registry. Caller must be owner. (`DeploymentController`)
   * @param templateCategory Category of the template to use.
   * @param templateId Unique Id of the template to use.
   * @param clone Address of the clone to add.
   */
  function addClone(
    bytes32 templateCategory,
    bytes32 templateId,
    address clone
  ) external onlyOwner {
    cloneExists[clone] = true;
    clones[templateCategory][templateId].push(clone);
    allClones.push(clone);

    emit CloneAdded(clone);
  }

  /*//////////////////////////////////////////////////////////////
                                VIEWS
    //////////////////////////////////////////////////////////////*/

  function getClonesByCategoryAndId(bytes32 templateCategory, bytes32 templateId)
    external
    view
    returns (address[] memory)
  {
    return clones[templateCategory][templateId];
  }

  function getAllClones() external view returns (address[] memory) {
    return allClones;
  }
}
"},"src/vault/DeploymentController.sol":{"content":"// SPDX-License-Identifier: GPL-3.0
// Docgen-SOLC: 0.8.15

pragma solidity ^0.8.15;

import { Owned } from "../utils/Owned.sol";
import { IOwned } from "../interfaces/IOwned.sol";
import { ICloneFactory } from "../interfaces/vault/ICloneFactory.sol";
import { ICloneRegistry } from "../interfaces/vault/ICloneRegistry.sol";
import { ITemplateRegistry, Template } from "../interfaces/vault/ITemplateRegistry.sol";

/**
 * @title   DeploymentController
 * @author  RedVeil
 * @notice  Bundles contracts for creating and registering clones.
 * @dev     Allows interacting with them via a single transaction.
 */
contract DeploymentController is Owned {
  /*//////////////////////////////////////////////////////////////
                               IMMUTABLES
    //////////////////////////////////////////////////////////////*/

  ICloneFactory public cloneFactory;
  ICloneRegistry public cloneRegistry;
  ITemplateRegistry public templateRegistry;

  /**
   * @notice Creates `DeploymentController`
   * @param _owner `AdminProxy`
   * @param _cloneFactory Creates clones.
   * @param _cloneRegistry Keeps track of new clones.
   * @param _templateRegistry Registry of templates used for deployments.
   * @dev Needs to call `acceptDependencyOwnership()` after the deployment.
   */
  constructor(
    address _owner,
    ICloneFactory _cloneFactory,
    ICloneRegistry _cloneRegistry,
    ITemplateRegistry _templateRegistry
  ) Owned(_owner) {
    cloneFactory = _cloneFactory;
    cloneRegistry = _cloneRegistry;
    templateRegistry = _templateRegistry;
  }

  /*//////////////////////////////////////////////////////////////
                          TEMPLATE LOGIC
    //////////////////////////////////////////////////////////////*/

  /**
   * @notice Adds a new category for templates. Caller must be owner. (`VaultController` via `AdminProxy`)
   * @param templateCategory A new template category.
   * @dev (See TemplateRegistry for more details)
   */
  function addTemplateCategory(bytes32 templateCategory) external onlyOwner {
    templateRegistry.addTemplateCategory(templateCategory);
  }

  /**
   * @notice Adds a new category for templates. Caller must be owner. (`VaultController` via `AdminProxy`)
   * @param templateCategory Category of the new template.
   * @param templateId Unique Id of the new template.
   * @param template New template (See ITemplateRegistry for more details)
   * @dev (See TemplateRegistry for more details)
   */
  function addTemplate(
    bytes32 templateCategory,
    bytes32 templateId,
    Template calldata template
  ) external {
    templateRegistry.addTemplate(templateCategory, templateId, template);
  }

  /**
   * @notice Toggles the endorsement of a template. Caller must be owner. (`VaultController` via `AdminProxy`)
   * @param templateCategory TemplateCategory of the template to endorse.
   * @param templateId TemplateId of the template to endorse.
   * @dev (See TemplateRegistry for more details)
   */
  function toggleTemplateEndorsement(bytes32 templateCategory, bytes32 templateId) external onlyOwner {
    templateRegistry.toggleTemplateEndorsement(templateCategory, templateId);
  }

  /*//////////////////////////////////////////////////////////////
                          DEPLOY LOGIC
    //////////////////////////////////////////////////////////////*/

  error NotEndorsed(bytes32 templateId);

  /**
   * @notice Clones an implementation and initializes the clone. Caller must be owner.  (`VaultController` via `AdminProxy`)
   * @param templateCategory Category of the template to use.
   * @param templateId Unique Id of the template to use.
   * @param data The data to pass to the clone's initializer.
   * @dev Uses a template from `TemplateRegistry`. The template must be endorsed.
   * @dev Deploys and initializes a clone using `CloneFactory`.
   * @dev Registers the clone in `CloneRegistry`.
   */
  function deploy(
    bytes32 templateCategory,
    bytes32 templateId,
    bytes calldata data
  ) external onlyOwner returns (address clone) {
    Template memory template = templateRegistry.getTemplate(templateCategory, templateId);

    if (!template.endorsed) revert NotEndorsed(templateId);

    clone = cloneFactory.deploy(template, data);

    cloneRegistry.addClone(templateCategory, templateId, clone);
  }

  /*//////////////////////////////////////////////////////////////
                          OWNERSHIP LOGIC
    //////////////////////////////////////////////////////////////*/

  /**
   * @notice Nominates a new owner for dependency contracts. Caller must be owner. (`VaultController` via `AdminProxy`)
   * @param _owner The new `DeploymentController` implementation
   */
  function nominateNewDependencyOwner(address _owner) external onlyOwner {
    IOwned(address(cloneFactory)).nominateNewOwner(_owner);
    IOwned(address(cloneRegistry)).nominateNewOwner(_owner);
    IOwned(address(templateRegistry)).nominateNewOwner(_owner);
  }

  /**
   * @notice Accept ownership of dependency contracts.
   * @dev Must be called after construction.
   */
  function acceptDependencyOwnership() external {
    IOwned(address(cloneFactory)).acceptOwnership();
    IOwned(address(cloneRegistry)).acceptOwnership();
    IOwned(address(templateRegistry)).acceptOwnership();
  }
}
"},"src/vault/PermissionRegistry.sol":{"content":"// SPDX-License-Identifier: GPL-3.0
// Docgen-SOLC: 0.8.15

pragma solidity ^0.8.15;

import { Owned } from "../utils/Owned.sol";
import { Permission } from "../interfaces/vault/IPermissionRegistry.sol";

/**
 * @title   PermissionRegistry
 * @author  RedVeil
 * @notice  Allows the DAO to endorse and reject addresses for security purposes.
 */
contract PermissionRegistry is Owned {
  /*//////////////////////////////////////////////////////////////
                            IMMUTABLES
    //////////////////////////////////////////////////////////////*/

  /// @param _owner `AdminProxy`
  constructor(address _owner) Owned(_owner) {}

  /*//////////////////////////////////////////////////////////////
                          PERMISSIONS
    //////////////////////////////////////////////////////////////*/

  mapping(address => Permission) public permissions;

  event PermissionSet(address target, bool newEndorsement, bool newRejection);

  error Mismatch();

  /**
   * @notice Set permissions for an array of target. Caller must be owner. (`VaultController` via `AdminProxy`)
   * @param targets `AdminProxy`
   * @param newPermissions An array of permissions to set for the targets.
   * @dev A permission can never be both endorsed and rejected.
   */
  function setPermissions(address[] calldata targets, Permission[] calldata newPermissions) external onlyOwner {
    uint256 len = targets.length;
    if (len != newPermissions.length) revert Mismatch();

    for (uint256 i = 0; i < len; i++) {
      if (newPermissions[i].endorsed && newPermissions[i].rejected) revert Mismatch();

      emit PermissionSet(targets[i], newPermissions[i].endorsed, newPermissions[i].rejected);

      permissions[targets[i]] = newPermissions[i];
    }
  }

  function endorsed(address target) external view returns (bool) {
    return permissions[target].endorsed;
  }

  function rejected(address target) external view returns (bool) {
    return permissions[target].rejected;
  }
}
